const choiceOrders=new Map();function choiceOrder(key,n){let o=choiceOrders.get(key);if(!o||o.length!==n){o=[...Array(n).keys()];for(let i=n-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[o[i],o[j]]=[o[j],o[i]];}choiceOrders.set(key,o);}return o;}
// Guest options: [textTr,textEn,whyTr,whyEn]; the first option listed is the correct one (display order is shuffled).
const gopt=([tr,en,whyTr,whyEn])=>({text:[tr,en],why:[whyTr,whyEn]});
function demoQuestion(areaTr,areaEn,qTr,qEn,options,source){return {area:[areaTr,areaEn],q:[qTr,qEn],options:options.map(gopt),answer:0,source};}
const guestQuestions=[
 demoQuestion('C# / .NET','C# / .NET','CLR’nin görevi hangisidir?','What is the CLR responsible for?',[
  ['.NET yönetilen kodunu çalıştırmak ve JIT, garbage collection gibi çalışma zamanı hizmetleri sağlamak.','Running managed .NET code and providing runtime services such as JIT compilation and garbage collection.','Doğru. C# derleyicisi IL ve metadata üretir; CLR bu IL’i yükler, makine koduna çevirir ve bellek yönetimi gibi hizmetleri sağlar.','Correct. The C# compiler emits IL and metadata; the CLR loads that IL, compiles it to machine code and provides services such as memory management.'],
  ['C# kaynak kodunu IL’e derlemek.','Compiling C# source code into IL.','Bu C# derleyicisinin (Roslyn) işidir. CLR’ye kaynak kod değil, derlenmiş IL gelir.','That is the C# compiler’s (Roslyn’s) job. The CLR receives compiled IL, not source code.'],
  ['NuGet paketlerini indirip proje bağımlılıklarını çözmek.','Downloading NuGet packages and resolving project dependencies.','Bu NuGet ve dotnet restore adımıdır ve derlemeden önce olur. CLR çalışma anında yalnızca derlenmiş assembly’leri yükler.','That is NuGet and dotnet restore, which run before the build. At run time the CLR only loads compiled assemblies.']],sources.clr),
 demoQuestion('C# / .NET','C# / .NET','Bir null referans hatasında ilk hangi bilgiyi incelemek daha yararlıdır?','When debugging a null-reference error, what should you inspect first?',[
  ['Stack trace’teki kaynak satırı ve orada kullanılan değerin nereden geldiği.','The source line in the stack trace and where the value used there came from.','Doğru. Stack trace hatanın oluştuğu yeri gösterir; değerin nerede üretildiğini izlemek hangi referansın neden boş olduğunu bulmanı sağlar.','Correct. The stack trace shows where the error happened; tracing where the value was produced tells you which reference is empty and why.'],
  ['Projeyi temizleyip yeniden derlemek (Clean + Rebuild).','Cleaning and rebuilding the project.','Rebuild eski derleme çıktılarını düzeltir ama null referans çalışma anındaki bir değer sorunudur. Yeniden derlemek hangi referansın boş olduğunu söylemez.','A rebuild fixes stale build output, but a null reference is a run-time value problem. Rebuilding does not tell you which reference is null.'],
  ['Hata veren satırı try/catch ile sarıp istisnayı yakalamak.','Wrapping the failing line in try/catch to catch the exception.','Bu sadece belirtiyi gizler. Değer hâlâ null’dır; sonraki kod yine hata verebilir ya da sessizce yanlış veri üretebilir.','This only hides the symptom. The value is still null, so later code may fail again or silently produce wrong data.']],{label:'Microsoft Learn',url:'https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/operators/member-access-operators'}),
 demoQuestion('JavaScript / React','JavaScript / React','React’te state değişince genellikle ne olur?','What generally happens when React state changes?',[
  ['React bileşeni yeni state ile tekrar render eder.','React renders the component again with the new state.','Doğru. State arayüzün girdisidir; set fonksiyonu yeni bir render planlar ve bileşen yeni değerle tekrar çizilir.','Correct. State is an input to the UI; the setter schedules a new render and the component is drawn again with the new value.'],
  ['State değişkeni aynı render içinde hemen yeni değeri gösterir.','The state variable shows the new value immediately within the same render.','State her render için bir anlık görüntü gibidir. Set çağrısından sonra mevcut render’daki değişken eski değeri tutar; yeni değer bir sonraki render’da görünür.','State behaves like a snapshot per render. After calling the setter, the variable in the current render still holds the old value; the new value appears on the next render.'],
  ['React tüm sayfayı DOM’dan silip baştan oluşturur.','React removes the whole page from the DOM and rebuilds it.','React yalnızca ilgili bileşeni ve alt bileşenlerini tekrar render eder, sonucu karşılaştırır ve DOM’da sadece değişen kısımları günceller.','React re-renders only the affected component and its children, compares the result, and updates just the changed parts of the DOM.']],{label:'React Docs',url:'https://react.dev/learn/state-a-components-memory'}),
 demoQuestion('JavaScript / React','JavaScript / React','React DOM’da bir buton tıklamasını hangi özellik ele alır?','Which prop handles a button click in React DOM?',[
  ['onClick','onClick','Doğru. React olay prop’ları camelCase yazılır; onClick’e bir fonksiyon verilir.','Correct. React event props are camelCase; you pass a function to onClick.'],
  ['onclick (HTML’deki gibi küçük harfle)','onclick (lowercase, as in HTML)','HTML’de bu çalışır ama JSX’te React olay prop’ları camelCase’tir. Küçük harfli onclick React’in olay işleyicisi olarak tanınmaz ve uyarı verir.','This works in HTML, but in JSX React event props are camelCase. Lowercase onclick is not recognized as a React event handler and triggers a warning.'],
  ['onPress','onPress','onPress React Native ve bazı bileşen kütüphanelerinde kullanılır. Tarayıcıdaki React DOM butonu onClick kullanır.','onPress is used in React Native and some component libraries. A React DOM button in the browser uses onClick.']],{label:'React Docs',url:'https://react.dev/learn/responding-to-events'}),
 demoQuestion('Git ve ekip çalışması','Git and collaboration','Push “non-fast-forward” ile reddedilirse güvenli ilk adım nedir?','A push is rejected as “non-fast-forward.” What is a safe first step?',[
  ['Uzak commitleri fetch edip farkları incelemek.','Fetch the remote commits and inspect the differences.','Doğru. Ret, uzakta sende olmayan commitler olduğunu gösterir. Önce onları gör; sonra ekip akışına göre merge veya rebase yapıp test et.','Correct. The rejection means the remote has commits you do not. See them first, then merge or rebase according to the team workflow and test.'],
  ['git push --force ile uzak branch’i kendi geçmişinle değiştirmek.','Replace the remote branch with your history using git push --force.','Force push, uzaktaki ama sende olmayan commitleri siler. Paylaşılan branch’te ekip arkadaşlarının işini kaybettirebilir.','A force push deletes the remote commits you do not have. On a shared branch it can destroy teammates’ work.'],
  ['git reset --hard origin/<branch> ile yerel branch’i uzak branch’e eşitlemek.','Match your local branch to the remote with git reset --hard origin/<branch>.','Bu komut kendi yerel commitlerini ve kaydedilmemiş değişikliklerini atar. Amaç iki geçmişi birleştirmek, kendi işini silmek değil.','This discards your own local commits and uncommitted changes. The goal is to combine both histories, not to delete your work.']],sources.git),
 demoQuestion('Git ve ekip çalışması','Git and collaboration','Bir pull request’in ana amacı nedir?','What is the main purpose of a pull request?',[
  ['Değişiklikleri birleştirmeden önce inceleme ve tartışmaya açmak.','To review and discuss changes before merging them.','Doğru. PR, değişiklikleri ekipçe gözden geçirmek, CI sonuçlarını görmek ve birleştirme kararı vermek için ortak bir alan sağlar.','Correct. A PR gives the team a place to review changes, see CI results and decide whether to merge.'],
  ['Değişiklikleri main branch’e hemen göndermenin kısa yolu olmak.','To be a shortcut for sending changes straight to main.','PR kendiliğinden birleştirmez; bir öneridir. Birleştirme inceleme ve onaydan sonra ayrıca yapılır.','A PR does not merge by itself; it is a proposal. Merging is a separate step after review and approval.'],
  ['Kodun yedeğini uzak sunucuda tutmak.','To keep a backup of the code on the remote server.','Branch’i pushlamak kodu zaten uzakta saklar. PR’ın kattığı şey yedek değil, inceleme, tartışma ve CI kontrolüdür.','Pushing the branch already stores the code remotely. What a PR adds is review, discussion and CI checks, not a backup.']],{label:'GitHub Docs',url:'https://docs.github.com/en/pull-requests/collaborating-with-pull-requests'}),
 demoQuestion('API / HTTP','API / HTTP','HTTP 401 yanıtı genellikle neyi belirtir?','What does an HTTP 401 response usually indicate?',[
  ['İstek geçerli kimlik doğrulaması sunmadı.','The request did not provide valid authentication.','Doğru. 401, kimlik bilgisinin eksik ya da geçersiz olduğunu gösterir; istemci geçerli bir kimlikle tekrar denemelidir.','Correct. 401 means credentials are missing or invalid; the client should retry with valid authentication.'],
  ['Kullanıcının kimliği doğrulandı ama bu kaynağa erişim yetkisi yok.','The user is authenticated but lacks permission for this resource.','Bu durum genellikle 403 Forbidden ile bildirilir. 401 kimlik doğrulama, 403 yetkilendirme sorunudur.','That is usually reported as 403 Forbidden. 401 is about authentication, 403 about authorization.'],
  ['İstek gövdesi geçersiz veya eksik alan içeriyor.','The request body is invalid or missing fields.','Geçersiz istek verisi genellikle 400 Bad Request (bazen 422) ile döner; kimlik doğrulamayla ilgili değildir.','Invalid request data usually returns 400 Bad Request (sometimes 422); it is not about authentication.']],{label:'MDN Web Docs',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/401'}),
 demoQuestion('API / HTTP','API / HTTP','JSON API yanıtında gövdenin içerik türünü hangi başlık bildirir?','Which header declares the content type of a JSON API response body?',[
  ['Content-Type: application/json','Content-Type: application/json','Doğru. Content-Type, gönderilen gövdenin medya türünü bildirir.','Correct. Content-Type declares the media type of the body being sent.'],
  ['Accept: application/json','Accept: application/json','Accept bir istek başlığıdır; istemcinin hangi türü kabul ettiğini söyler. Yanıt gövdesinin türünü tanımlamaz.','Accept is a request header that says which types the client accepts. It does not describe the response body.'],
  ['Content-Encoding: json','Content-Encoding: json','Content-Encoding gzip veya br gibi sıkıştırmayı anlatır; medya türünü değil. “json” geçerli bir encoding değeri de değildir.','Content-Encoding describes compression such as gzip or br, not the media type. “json” is not a valid encoding value either.']],{label:'MDN Web Docs',url:'https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Content-Type'}),
 demoQuestion('SQL / veri modeli','SQL / data modeling','WHERE ile GROUP BY arasındaki temel fark nedir?','What is the main difference between WHERE and GROUP BY?',[
  ['WHERE satırları gruplamadan önce filtreler; GROUP BY kalan satırları gruplar.','WHERE filters rows before grouping; GROUP BY groups the remaining rows.','Doğru. WHERE tek tek satırları eler; GROUP BY kalan satırları ortak değerlere göre toplar ve COUNT, SUM gibi fonksiyonlara hazırlar.','Correct. WHERE removes individual rows; GROUP BY collects the remaining rows by shared values for aggregates like COUNT and SUM.'],
  ['WHERE grupları filtreler; GROUP BY satırları sıralar.','WHERE filters groups; GROUP BY sorts rows.','Grupları filtrelemek HAVING’in işidir, sıralamak ORDER BY’ın. GROUP BY belirli bir sıra garanti etmez.','Filtering groups is HAVING’s job and sorting is ORDER BY’s. GROUP BY does not guarantee any order.'],
  ['İkisi de satırları filtreler; GROUP BY yalnızca daha hızlıdır.','Both filter rows; GROUP BY is just faster.','GROUP BY filtrelemez; satırları gruplara indirger. İki ifade sorgunun farklı aşamalarında farklı işler yapar.','GROUP BY does not filter; it collapses rows into groups. The two clauses do different jobs at different stages of the query.']],{label:'PostgreSQL Docs',url:'https://www.postgresql.org/docs/current/queries-table-expressions.html'}),
 demoQuestion('SQL / veri modeli','SQL / data modeling','LEFT JOIN sonucu için hangisi doğrudur?','Which statement about a LEFT JOIN is correct?',[
  ['Sol tablodaki tüm satırlar korunur; eşleşme yoksa sağ sütunlar NULL olur.','All left-table rows are kept; right-side columns are NULL when there is no match.','Doğru. LEFT JOIN sol tablodaki her satırı sonuçta tutar; sağda eşleşme yoksa o sütunları NULL ile doldurur.','Correct. A LEFT JOIN keeps every left-table row and fills right-side columns with NULL when nothing matches.'],
  ['Yalnızca iki tabloda da eşleşen satırlar döner.','Only rows that match in both tables are returned.','Bu INNER JOIN’in davranışıdır. LEFT JOIN eşleşmeyen sol satırları da korur.','That is how an INNER JOIN behaves. A LEFT JOIN also keeps unmatched left rows.'],
  ['Sol tablodaki her satır sonuçta en fazla bir kez görünür.','Each left-table row appears at most once in the result.','Sağ tabloda birden fazla eşleşme varsa sol satır her eşleşme için tekrar eder. Bu, beklenmedik satır çoğalmasının yaygın sebebidir.','If the right table has several matches, the left row repeats once per match. This is a common cause of unexpected row multiplication.']],{label:'PostgreSQL Docs',url:'https://www.postgresql.org/docs/current/tutorial-join.html'}),
 demoQuestion('Unity / C#','Unity / C#','Unity’de Inspector’dan atanmış bir nesne çalışma anında null ise önce neyi kontrol edersin?','A Unity object assigned in the Inspector is null at runtime. What do you check first?',[
  ['Doğru nesnenin doğru bileşendeki alana atanıp atanmadığını ve referansın yok edilip edilmediğini.','Whether the right object is assigned to the field on the right component, and whether it was destroyed.','Doğru. Atama başka bir kopyada (ör. prefab ya da başka sahne nesnesi) yapılmış olabilir veya nesne Destroy edilmiş olabilir; Unity yok edilen nesneyi null gibi gösterir.','Correct. The assignment may be on a different instance (a prefab or another scene object), or the object may have been destroyed; Unity reports destroyed objects as null.'],
  ['Alanı public yerine private yapmak.','Changing the field from public to private.','private alanlar [SerializeField] olmadan Inspector’da görünmez ve serileştirilmez. Bu, sorunu çözmez; atamayı tamamen kaybettirir.','Private fields without [SerializeField] are not shown in the Inspector or serialized. This does not fix anything; it loses the assignment entirely.'],
  ['Unity Editör’ü yeniden başlatıp sahneyi tekrar yüklemek.','Restarting the Unity Editor and reloading the scene.','Nadir bir editör aksaklığını giderebilir ama hangi atamanın eksik olduğunu göstermez. Atama gerçekten eksikse referans yine null olur.','It may clear a rare editor glitch, but it does not show which assignment is missing. If the assignment really is missing, the reference stays null.']],{label:'Unity Scripting API',url:'https://docs.unity3d.com/ScriptReference/SerializeField.html'}),
 demoQuestion('Unity / C#','Unity / C#','Fizik tabanlı Rigidbody hareketini hangi döngüde güncellemek genellikle uygundur?','Which loop is generally appropriate for updating Rigidbody physics?',[
  ['FixedUpdate','FixedUpdate','Doğru. FixedUpdate sabit zaman adımında, fizik simülasyonuyla aynı ritimde çalışır; kuvvet ve hız uygulamak için uygundur.','Correct. FixedUpdate runs on a fixed timestep in step with the physics simulation, so it suits applying forces and velocity.'],
  ['Update','Update','Update her frame’de çalışır ve frame süresi değişkendir. Fizik kuvvetlerini burada uygulamak frame hızına bağlı sonuç verir; girdiyi Update’te oku, fiziği FixedUpdate’te uygula.','Update runs every frame with a variable frame time. Applying physics forces there gives frame-rate-dependent results; read input in Update, apply physics in FixedUpdate.'],
  ['LateUpdate','LateUpdate','LateUpdate her frame’de Update’lerden sonra çalışır; genellikle kamera takibi için kullanılır. Fizik adımıyla eşzamanlı değildir.','LateUpdate runs every frame after all Updates and is typically used for camera follow. It is not synchronized with the physics step.']],{label:'Unity Manual',url:'https://docs.unity3d.com/Manual/execution-order.html'}),
 demoQuestion('DevOps / CI','DevOps / CI','GitHub Actions workflow’unu bir push sonrasında başlatan yaygın yapılandırma nedir?','Which common GitHub Actions configuration starts a workflow after a push?',[
  ['on: push','on: push','Doğru. Tetikleyiciler `on` alanında tanımlanır; `push` bir branch’e commit gönderilince workflow’u çalıştırır.','Correct. Triggers are declared under `on`; `push` runs the workflow when commits are pushed to a branch.'],
  ['on: pull_request','on: pull_request','Bu da bir tetikleyicidir ama pull request açılınca veya güncellenince çalışır; doğrudan bir branch’e yapılan push’ta değil.','This is also a trigger, but it runs when a pull request is opened or updated, not on a direct push to a branch.'],
  ['runs-on: push','runs-on: push','`runs-on` job’un çalışacağı makineyi (ör. ubuntu-latest) seçer; tetikleyici değildir.','`runs-on` picks the machine a job runs on (e.g. ubuntu-latest); it is not a trigger.']],{label:'GitHub Docs',url:'https://docs.github.com/en/actions/writing-workflows/workflow-syntax-for-github-actions#on'}),
 demoQuestion('DevOps / CI','DevOps / CI','Bir Actions workflow’unda API anahtarını nasıl saklamak daha güvenlidir?','How should an API key be stored in a GitHub Actions workflow?',[
  ['GitHub Actions secrets olarak saklayıp `${{ secrets.NAME }}` ile kullanmak.','Store it as a GitHub Actions secret and use `${{ secrets.NAME }}`.','Doğru. Secrets şifreli saklanır ve loglarda maskelenir. Workflow’a da yalnızca gerektiği kadar izin ver.','Correct. Secrets are stored encrypted and masked in logs. Also grant the workflow only the permissions it needs.'],
  ['Workflow dosyasında env: altına değer olarak yazmak.','Write the value under env: in the workflow file.','Workflow dosyası repoda durur; okuma izni olan herkes anahtarı görür ve değer git geçmişinde kalır.','The workflow file lives in the repository; anyone with read access sees the key and it stays in git history.'],
  ['Repository variables olarak saklayıp `${{ vars.NAME }}` ile kullanmak.','Store it as a repository variable and use `${{ vars.NAME }}`.','Variables hassas olmayan ayarlar içindir ve loglarda maskelenmez. Gizli değerler için secrets kullanılmalıdır.','Variables are for non-sensitive settings and are not masked in logs. Sensitive values belong in secrets.']],{label:'GitHub Docs',url:'https://docs.github.com/en/actions/security-for-github-actions/security-guides/using-secrets-in-github-actions'}),
 demoQuestion('Test ve doğrulama','Testing and validation','Bir unit testin temel amacı nedir?','What is the main purpose of a unit test?',[
  ['Küçük bir birimin davranışını belirli girdilerle, yalıtılmış olarak doğrulamak.','Verify a small unit’s behavior for specific inputs, in isolation.','Doğru. Unit test küçük bir davranışın beklenen sonucu verip vermediğini hızlı ve tekrar edilebilir biçimde kontrol eder.','Correct. A unit test checks quickly and repeatably whether a small behavior produces the expected result.'],
  ['Tüm bileşenlerin gerçek veritabanı ve servislerle birlikte çalıştığını doğrulamak.','Verify that all components work together with the real database and services.','Bu entegrasyon veya uçtan uca testin amacıdır. Unit test bağımlılıklardan yalıtılmış küçük bir parçayı test eder.','That is the goal of integration or end-to-end tests. A unit test checks a small piece isolated from its dependencies.'],
  ['Kod satırlarının %100’ünün çalıştırıldığını kanıtlamak.','Prove that 100% of code lines are executed.','Coverage bir ölçümdür, amaç değildir. Satırın çalışması doğru sonucu verdiğini göstermez; asıl iş beklenen sonucu kontrol etmektir.','Coverage is a metric, not the goal. Running a line does not show it gives the right result; the real job is checking expected outcomes.']],{label:'Microsoft Learn',url:'https://learn.microsoft.com/en-us/dotnet/core/testing/'}),
 demoQuestion('Test ve doğrulama','Testing and validation','Bir testte gerçek e-posta servisi yerine sahte (mock) servis kullanmanın amacı ne olabilir?','Why might a test use a mock instead of a real email service?',[
  ['Testi dış servisten bağımsız, hızlı ve öngörülebilir tutmak.','Keep the test independent of the external service, fast and predictable.','Doğru. Mock dış bağımlılığın yerine kontrollü bir davranış koyar; böylece test yalnızca senin kodunu ölçer.','Correct. A mock replaces the external dependency with controlled behavior, so the test measures only your code.'],
  ['Gerçek e-posta servisinin doğru çalıştığını kanıtlamak.','Prove that the real email service works correctly.','Mock gerçek servisin yerini aldığı için onun çalıştığını kanıtlayamaz. Gerçek sınırı entegrasyon testleri ayrıca doğrulamalıdır.','Because the mock replaces the real service, it cannot prove that service works. Integration tests must verify the real boundary separately.'],
  ['Testin her çalıştırmada farklı, gerçekçi sonuçlar üretmesini sağlamak.','Make the test produce different, realistic results on each run.','Tam tersi: mock davranışı sabitler. Her seferinde farklı sonuç veren test kararsız (flaky) olur ve güven vermez.','The opposite: a mock fixes the behavior. A test that gives different results each run is flaky and cannot be trusted.']],{label:'Microsoft Learn',url:'https://learn.microsoft.com/en-us/dotnet/core/testing/unit-testing-best-practices'}),
 demoQuestion('AI mühendisliği','AI engineering','Bir RAG sisteminde retrieval adımı ne yapar?','What does the retrieval step do in a RAG system?',[
  ['Soruyla ilgili kaynak parçalarını bulup modele bağlam olarak verir.','Finds relevant source passages and gives them to the model as context.','Doğru. Retrieval ilgili içeriği getirir ve modelin isteğine ekler; model yanıtı bu bağlamla üretir.','Correct. Retrieval fetches relevant content and adds it to the model’s request; the model then answers using that context.'],
  ['Modeli şirket belgeleriyle yeniden eğitir (fine-tune).','Retrains (fine-tunes) the model on company documents.','RAG modelin ağırlıklarını değiştirmez; belgeleri her istekte bağlam olarak ekler. Fine-tuning ayrı bir eğitim sürecidir.','RAG does not change model weights; it adds documents as context on each request. Fine-tuning is a separate training process.'],
  ['Üretilen yanıtın kaynaklarla uyumlu olduğunu doğrular.','Verifies that the generated answer matches the sources.','Retrieval yanıt üretilmeden önce çalışır ve doğruluk garantisi vermez. Yanıtın kaynaklara uyumu ayrı bir değerlendirme adımıdır.','Retrieval runs before the answer is generated and does not guarantee correctness. Checking the answer against sources is a separate evaluation step.']],{label:'OpenAI Docs',url:'https://platform.openai.com/docs/guides/retrieval'}),
 demoQuestion('AI mühendisliği','AI engineering','Kullanıcıdan gelen belge içindeki “önceki kuralları yok say” ifadesi nasıl ele alınmalı?','How should “ignore previous rules” inside a user-provided document be treated?',[
  ['Güvenilmeyen içerik olarak ele al; talimat ya da yetki kaynağı sayma.','Treat it as untrusted content, not as an instruction or a source of authority.','Doğru. Belge metni veridir. İçerik ile talimatı ayır ve araç erişimini ayrıca sınırla; bu prompt injection riskini azaltır.','Correct. Document text is data. Separate content from instructions and constrain tool access independently to reduce prompt-injection risk.'],
  ['Belgeyi kullanıcı yüklediği için talimata uymak.','Follow it because the user uploaded the document.','Belgeyi yüklemek, içindeki her cümleyi kullanıcının isteği yapmaz; belge üçüncü bir kişiden gelmiş olabilir. Görevi kullanıcının kendi isteği belirler.','Uploading a document does not make every sentence in it the user’s request; it may come from a third party. The user’s own request defines the task.'],
  ['Yalnızca bu cümleyi filtreleyip belgedeki diğer talimatları uygulamak.','Filter out just this sentence and follow the document’s other instructions.','Anahtar kelime filtresi kolayca atlatılır ve sorun yalnızca bu cümle değildir. Belgenin tamamı veri olarak kalmalı; içindeki talimatlar uygulanmamalıdır.','Keyword filters are easy to bypass, and the problem is not only this sentence. The whole document stays data; instructions inside it should not be executed.']],{label:'OpenAI Docs',url:'https://platform.openai.com/docs/guides/agent-builder-safety'}),
 demoQuestion('Veri mühendisliği','Data engineering','Bir ETL adımı aynı dosyayı tekrar işlerse yinelenen kayıtları önleyen tasarım özelliği nedir?','What design property prevents duplicate records when an ETL step reprocesses a file?',[
  ['Idempotency: aynı girdiyi tekrar uygulamak aynı sonucu üretir.','Idempotency: applying the same input again produces the same result.','Doğru. Idempotent bir adım tekrar çalışınca yan etkiyi çoğaltmaz; benzersiz anahtar ve upsert ile sağlanabilir.','Correct. An idempotent step does not multiply side effects when rerun; unique keys and upserts can provide it.'],
  ['Hata olunca adımı otomatik yeniden denemek (retry).','Automatically retrying the step on failure.','Retry tek başına yinelemeyi önlemez; adım idempotent değilse yinelenen kayıtları tam olarak retry üretir.','Retry alone does not prevent duplicates; if the step is not idempotent, retries are exactly what create them.'],
  ['Paralel çalışan worker sayısını artırmak.','Increasing the number of parallel workers.','Bu hız ile ilgilidir, tekrar işleme ile değil. Koordinasyon yoksa aynı dosyanın iki kez işlenme ihtimalini artırabilir.','This is about throughput, not reprocessing. Without coordination it can make processing the same file twice more likely.']],{label:'DataTalksClub Zoomcamp',url:'https://github.com/DataTalksClub/data-engineering-zoomcamp'}),
 demoQuestion('Veri mühendisliği','Data engineering','Büyük tabloda sık kullanılan filtre sütununa indeks eklemenin temel amacı nedir?','What is the main purpose of indexing a frequently filtered column in a large table?',[
  ['Bazı sorgularda aramayı hızlandırmak; yazma ve depolama maliyetini de hesaba katmak.','Speed up some lookups while accounting for write and storage costs.','Doğru. İndeks okuma erişimini hızlandırabilir ama disk kullanır ve her yazmada güncellenir; sorgu planını ölçerek karar ver.','Correct. An index can speed up reads but uses disk and is updated on every write; decide by measuring the query plan.'],
  ['O sütunu kullanan her sorgunun daha hızlı çalışmasını garanti etmek.','Guarantee that every query on that column runs faster.','Planlayıcı indeksi kullanmayabilir (ör. satırların çoğu eşleşiyorsa) ve yazma işlemleri yavaşlar. Hızlanma garanti değildir.','The planner may skip the index (e.g. when most rows match) and writes get slower. Speed-up is not guaranteed.'],
  ['Sütundaki değerlerin benzersiz olmasını sağlamak.','Ensure the column’s values are unique.','Bunu yalnızca UNIQUE indeks veya kısıt yapar. Normal indeks tekrar eden değerlere izin verir; filtre sütunu için amaç hızdır.','Only a UNIQUE index or constraint does that. A normal index allows duplicates; for a filter column the goal is speed.']],{label:'PostgreSQL Docs',url:'https://www.postgresql.org/docs/current/indexes-intro.html'}),
 demoQuestion('Mobil geliştirme','Mobile development','Android’de ekran döndürülünce Activity yeniden oluşturulursa geçici UI durumunu korumak için ne kullanılır?','If an Android Activity is recreated on rotation, what can preserve transient UI state?',[
  ['ViewModel veya saved state gibi lifecycle’a duyarlı bir durum mekanizması.','A lifecycle-aware mechanism such as a ViewModel or saved state.','Doğru. ViewModel yapılandırma değişikliklerinden sağ çıkar; saved state ise süreç sonlansa bile küçük UI durumunu geri getirir.','Correct. A ViewModel survives configuration changes; saved state restores small UI state even after process death.'],
  ['Durumu Activity içinde bir static değişkende tutmak.','Keeping the state in a static variable in the Activity.','Static alan süreç sonlanınca kaybolur ve Context gibi nesneleri tutarsa bellek sızıntısına yol açar. Lifecycle’a bağlı değildir.','A static field is lost on process death and leaks memory if it holds objects like a Context. It is not tied to the lifecycle.'],
  ['Manifest’te ekran yönünü kilitlemek.','Locking the screen orientation in the manifest.','Bu yalnızca döndürmeyi engeller. Dil, karanlık mod veya çoklu pencere gibi diğer değişiklikler ve süreç sonlanması Activity’yi yine yeniden oluşturur.','This only blocks rotation. Other changes like language, dark mode or multi-window, and process death, still recreate the Activity.']],{label:'Android Developers',url:'https://developer.android.com/topic/libraries/architecture/saving-states'}),
 demoQuestion('Mobil geliştirme','Mobile development','Mobil uygulama bir konum iznini ne zaman istemelidir?','When should a mobile app request location permission?',[
  ['Kullanıcı konum gerektiren bir özelliği başlattığında, amacını açıklayarak.','When the user starts a feature that needs location, explaining why.','Doğru. İzni ihtiyaç anında iste ve amacını açıkla; reddedilirse uygulamanın nasıl davranacağını da tasarla.','Correct. Ask at the point of need and explain the purpose; also design how the app behaves if the user declines.'],
  ['İlk açılışta tüm izinleri tek seferde istemek.','Requesting all permissions at once on first launch.','Bağlam olmadan istenen izinler daha sık reddedilir. Android rehberi izni ilgili özellik kullanılırken istemeyi önerir.','Permissions asked without context are denied more often. Android guidance recommends asking when the related feature is used.'],
  ['Kullanıcı reddederse izin penceresini her açılışta tekrar göstermek.','Showing the permission dialog again on every launch after a denial.','Tekrarlanan retlerden sonra sistem pencereyi göstermeyi bırakabilir ve bu ısrar kullanıcıyı rahatsız eder. Bunun yerine özelliği izinsiz de kullanılabilir tasarla.','After repeated denials the system may stop showing the dialog, and nagging annoys users. Design the feature to degrade gracefully instead.']],{label:'Android Developers',url:'https://developer.android.com/training/permissions/requesting'}),
 demoQuestion('Oyun geliştirme','Game development','Unity oyununda fizik etkili nesnenin hareketini her frame `transform` ile doğrudan değiştirmek neden sorun çıkarabilir?','Why can directly changing a physics-driven object’s transform every frame cause problems in Unity?',[
  ['Fizik motorunun simülasyonuyla çakışır; Rigidbody hareket API’leri ve fizik adımı tercih edilmelidir.','It conflicts with the physics simulation; Rigidbody movement APIs and the physics step should be used.','Doğru. Transform’u değiştirmek nesneyi ışınlar; çarpışma çözümü ve interpolasyon atlanır. Rigidbody.MovePosition veya hız kullanmak simülasyonu tutarlı tutar.','Correct. Changing the transform teleports the object, skipping collision resolution and interpolation. Rigidbody.MovePosition or velocity keeps the simulation consistent.'],
  ['Her frame transform değiştirmek çok fazla garbage collection üretir.','Changing the transform every frame creates lots of garbage collection.','transform.position atamak bellek ayırmaz; GC sorunu yaratmaz. Asıl sorun fizik motorunu atlamaktır.','Assigning transform.position does not allocate memory, so it does not cause GC pressure. The real problem is bypassing the physics engine.'],
  ['Sorun çıkarmaz; Unity transform değişikliğini fizik motoruna sorunsuz aktarır.','It causes no problems; Unity passes transform changes to physics seamlessly.','Unity transform’u fiziğe senkronlar ama bunu ışınlama olarak yapar. Sonuç titreme, duvarlardan geçme ve hatalı çarpışmalardır.','Unity syncs the transform to physics, but as a teleport. The result is jitter, passing through walls and wrong collisions.']],{label:'Unity Manual',url:'https://docs.unity3d.com/Manual/physics-rigidbody.html'}),
 demoQuestion('Oyun geliştirme','Game development','Bir oyun karakteri için zıplama girdisini kabul etmeden önce neyi kontrol etmek gerekir?','What should be checked before accepting a jump input for a game character?',[
  ['Karakterin yerde olup olmadığını ve girdinin tek bir basış olarak işlenmesini.','Whether the character is grounded and whether the input is handled as a single press.','Doğru. Yerde olma kontrolü ve girdiyi basış anında (GetKeyDown gibi) işlemek, havada tekrar zıplama gibi hataları önler.','Correct. A grounded check and handling input on the press (like GetKeyDown) prevent bugs such as repeated midair jumps.'],
  ['Zıplama tuşunun basılı olup olmadığını her frame GetKey ile kontrol etmek.','Checking every frame with GetKey whether the jump key is held.','GetKey tuş basılı kaldıkça her frame true döner; karakter tekrar tekrar zıplar. Tek seferlik eylemler için basış anı kontrol edilmelidir.','GetKey returns true every frame while the key is held, so the character jumps repeatedly. One-off actions should check the press moment.'],
  ['Karakterin dikey hızının sıfır olup olmadığını.','Whether the character’s vertical velocity is zero.','Dikey hız zıplamanın tepe noktasında da sıfırdır; bu kontrol havada zıplamaya izin verir. Yeri raycast veya temas kontrolüyle tespit et.','Vertical velocity is also zero at the top of a jump, so this check allows midair jumps. Detect the ground with a raycast or contact check.']],{label:'Unity Learn',url:'https://learn.unity.com/'})
];
function feedbackBox(ok,picked,right,t,src){const clean=s=>esc(s).replace(/^(Doğru|Correct)\.\s*/,'');return `<div class="result-box ${ok?'':'warning'}"><h4>${ok?t.ok:picked?t.wrong:t.skip}</h4>${ok?`<p>${clean(right.why)}</p>`:`${picked?`<p><strong>${t.picked}</strong> ${esc(picked.why)}</p>`:''}<p><strong>${t.right} ${esc(right.text)}</strong><br>${clean(right.why)}</p>`}<div style="margin-top:8px;font-size:10px">${src}</div></div>`;}
let state={view:'today',quizIndex:0,quizMode:false,selected:null,answered:false,completed:0,answerText:'',errorSolved:false,conceptOpen:null,newsSummaries:{},errorHint:0};
const root=document.getElementById('viewRoot');
let signedIn=Boolean(window.realdevCurrentUser?.emailVerified),sessionKnown=signedIn,canSignIn=false,guestQuizIndex=0,guestSelected=null,guestAnswered=false,guestConceptOpen=null;
function progressKey(){const uid=window.realdevCurrentUser?.uid;return signedIn&&uid?`realdev-progress:${uid}`:null}
function loadProgress(){const key=progressKey();if(!key)return;try{const stored=JSON.parse(localStorage.getItem(key)||'{}');Object.assign(state,{completed:stored.completed||0,errorSolved:stored.errorSolved||false,answerText:stored.answerText||''});}catch{}}
loadProgress();
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function save(){const key=progressKey();if(!key)return;localStorage.setItem(key,JSON.stringify({completed:state.completed,errorSolved:state.errorSolved,answerText:state.answerText}))}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function link(source,label='Kaynağı aç'){return `<a href="${source.url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}
function heading(eyebrow,title,desc,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${right}</div>`}
const guestLocale=()=>window.realdevLocale==='en'?'en':'tr';
const bilingual=(tr,en)=>guestLocale()==='en'?en:tr;
function publicConcepts(){const bank=window.realdevContentBank||{cards:[],sources:{}};return [...concepts,...expandedConcepts,...bank.cards.map(x=>({...x,source:{label:bank.sources[x.source]?.name||x.source,url:bank.sources[x.source]?.url||'#'}}))].slice(0,10);}
function publicLanding(){const en=guestLocale()==='en';return `<section class="public-hero"><div class="eyebrow">REALDEVELOPER · DEVELOPER PRACTICE STUDIO</div><h1>${en?'Build confidence by explaining the code you use.':'Kullandığın kodu açıklayarak gerçek becerini geliştir.'}</h1><p>${en?'A guided practice space for developers: read code, diagnose realistic errors, explain technical concepts, and build a learning path from evidence.':'Yazılımcılar için uygulamalı çalışma alanı: kodu oku, gerçekçi hataları teşhis et, teknik kavramları açıkla ve kanıta dayalı bir öğrenme rotası oluştur.'}</p><div class="public-hero-actions"><a class="primary-button" href="/auth.html#/sign-up">${en?'Create a free account':'Ücretsiz hesap oluştur'} →</a><a class="secondary-button" href="/demo/questions" data-public-view="demoQuiz">${en?'Try sample questions':'Örnek soruları dene'}</a></div><div class="public-note">${en?'Explore the public samples without an account. Sign in to save answers, notes and your personal progress.':'Örnekleri hesapsız incele. Cevaplarını, notlarını ve kişisel ilerlemeni kaydetmek için giriş yap.'}</div></section><section class="public-section"><div><div class="eyebrow">${en?'WHAT YOU CAN PRACTICE':'NELER ÇALIŞABİLİRSİN'}</div><h2>${en?'Practice the work, not just the vocabulary.':'Sadece kavramı değil, yazılım işini çalış.'}</h2></div><div class="public-feature-grid"><article><span>01 · ${en?'REASON':'AKIL YÜRÜT'}</span><h3>${en?'Read and write code':'Kod oku ve yaz'}</h3><p>${en?'Predict behavior, run focused exercises, and explain decisions in your own words.':'Kod davranışını tahmin et, odaklı görevleri çöz ve kararlarını kendi cümlelerinle açıkla.'}</p></article><article><span>02 · ${en?'DEBUG':'HATA AYIKLA'}</span><h3>${en?'Learn from real errors':'Gerçek hatalardan öğren'}</h3><p>${en?'Practice safe Git, API, IDE, .NET and Unity troubleshooting with visible evidence.':'Git, API, IDE, .NET ve Unity hatalarını kanıta bakarak güvenli biçimde teşhis et.'}</p></article><article><span>03 · ${en?'GROW':'GELİŞ'}</span><h3>${en?'Follow your own route':'Kendi rotanı izle'}</h3><p>${en?'After sign-in, your profile, notes, answer history, skill map and study route stay tied to your account.':'Girişten sonra profilin, notların, cevap geçmişin, beceri haritan ve çalışma rotan hesabına bağlı tutulur.'}</p></article></div></section><section class="public-section public-samples"><div><div class="eyebrow">${en?'OPEN PREVIEW':'AÇIK ÖNİZLEME'}</div><h2>${en?'Try a small sample':'Küçük bir örnek dene'}</h2><p>${en?'Guests can answer two sample questions in each preview topic and browse ten sourced concept cards. Guest answers are temporary and are never saved.':'Misafirler her örnek konu başlığında iki soruyu çözebilir ve kaynaklı on kavram kartını inceleyebilir. Misafir cevapları geçicidir, kaydedilmez.'}</p></div><div class="public-sample-actions"><a class="secondary-button" href="/demo/questions" data-public-view="demoQuiz">${en?'Open sample questions':'Örnek testleri aç'} →</a><a class="secondary-button" href="/demo/concepts" data-public-view="demoConcepts">${en?'Browse 10 concepts':'10 kavrama göz at'} →</a></div></section><section class="public-section"><h2>${en?'Read sourced explanations':'Kaynaklı anlatımları oku'}</h2><p><a href="${en?'/en/learn':'/learn'}">${en?'Public concept library →':'Herkese açık kavram kütüphanesi →'}</a></p></section><section class="public-bottom"><h2>${en?'Your learning history starts after sign-in.':'Kişisel çalışma geçmişin giriş yaptıktan sonra başlar.'}</h2><p>${en?'Create an account to unlock the complete skill assessment, code lab, interview projects, saved notes and personalized study route.':'Tam beceri taramasını, kod alanını, mülakat projelerini, kayıtlı notlarını ve kişisel çalışma rotanı açmak için hesap oluştur.'}</p><a class="primary-button" href="/auth.html#/sign-up">${en?'Sign up / sign in':'Kayıt ol / giriş yap'} →</a></section>`;}
function guestQuizView(){const en=guestLocale()==='en';const q=guestQuestions[guestQuizIndex];if(!q)return `<section class="public-demo-card"><div class="eyebrow">${en?'SAMPLE COMPLETE':'ÖRNEK TAMAMLANDI'}</div><h1>${en?'That was the preview.':'Örnek tur tamamlandı.'}</h1><p>${en?'Your guest answers were only held temporarily and were not saved. Sign in to keep a learning history and unlock the full practice library.':'Misafir cevapların geçici olarak tutuldu, kaydedilmedi. Cevap geçmişini saklamak ve tüm çalışma kütüphanesini açmak için giriş yap.'}</p><div class="public-hero-actions"><a class="primary-button" href="/auth.html#/sign-up">${en?'Create an account':'Hesap oluştur'} →</a><button class="secondary-button" data-public-view="landing">${en?'Back to home':'Ana sayfaya dön'}</button></div></section>`;return `<section class="public-demo-card"><button class="text-button" data-public-view="landing">← ${en?'Public home':'Tanıtım sayfası'}</button><div class="quiz-top"><span class="eyebrow">${q.area[en?1:0]}</span><span class="quiz-step">${guestQuizIndex+1} / ${guestQuestions.length}</span></div><div class="progress"><span style="width:${(guestQuizIndex+1)/guestQuestions.length*100}%"></span></div><h1 class="quiz-question">${q.q[en?1:0]}</h1><div class="choice-list">${choiceOrder('guest:'+guestQuizIndex,q.options.length).map((index,position)=>`<button class="choice ${guestAnswered&&guestSelected===index?'selected':''}" data-guest-choice="${index}" ${guestAnswered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+position)}</span><span>${esc(q.options[index].text[en?1:0])}</span></button>`).join('')}</div>${guestAnswered?feedbackBox(guestSelected===q.answer,(o=>o&&{text:o.text[en?1:0],why:o.why[en?1:0]})(q.options[guestSelected]),{text:q.options[q.answer].text[en?1:0],why:q.options[q.answer].why[en?1:0]},en?{ok:'Correct.',wrong:'Not quite.',skip:'Here is the answer.',picked:'Why your choice is wrong:',right:'Correct answer:'}:{ok:'Doğru.',wrong:'Bu seçenek doğru değil.',skip:'Doğru cevap şöyle.',picked:'Seçtiğin neden yanlış:',right:'Doğru cevap:'},link(q.source,en?'Reference':'Kaynak')):''}<div class="quiz-actions"><span class="text-muted">${en?'Guest answers are not saved.':'Misafir cevapları kaydedilmez.'}</span>${guestAnswered?`<button class="primary-button" data-guest-action="next">${guestQuizIndex===guestQuestions.length-1?(en?'Finish':'Bitir'):(en?'Next':'Sonraki')} →</button>`:''}</div></section>`;}
function guestConceptsView(){const en=guestLocale()==='en',cards=publicConcepts(),selected=cards.find(x=>x.id===guestConceptOpen);const value=x=>typeof x==='string'?x:(x?.[en?'en':'tr']||x?.tr||'');const name=x=>value(x.name||x.title);const desc=x=>value(x.desc||x.description);const body=x=>value(x.body||x.explanation||x.desc);return `<section class="public-demo-card"><button class="text-button" data-public-view="landing">← ${en?'Public home':'Tanıtım sayfası'}</button><div class="eyebrow">${en?'10 OPEN CONCEPTS':'AÇIK 10 KAVRAM'}</div><h1>${en?'A small glossary to start with.':'Başlangıç için kısa bir kavram kütüphanesi.'}</h1><p>${en?'Read sourced explanations and follow the original references. Personal notes and the full library are available after sign-in.':'Kaynaklı açıklamaları ve özgün referansları incele. Kişisel notlar ve tam kütüphane girişten sonra açılır.'}</p><div class="concept-grid">${cards.map(x=>`<a class="concept-card" href="#concept-${encodeURIComponent(x.id)}" data-guest-concept="${esc(x.id)}"><span class="concept-type">${esc(value(x.type)|| (en?'Concept':'Kavram'))}</span><h3>${esc(name(x))}</h3><p>${esc(desc(x))}</p><div class="concept-footer"><span>${en?'Sourced':'Kaynaklı'}</span><span>${en?'Read':'İncele'} →</span></div></a>`).join('')}</div>${selected?`<article class="concept-detail"><div class="eyebrow">${esc(value(selected.type))}</div><h2>${esc(name(selected))}</h2><div class="concept-body">${esc(body(selected)).replace(/\n/g,'<br>')}</div>${selected.analogy?`<div class="analogy"><strong>${en?'Example:':'Örnek:'}</strong> ${esc(value(selected.analogy))}</div>`:''}${selected.source?.url&&selected.source.url!=='#'?`<div class="source-note" style="margin-top:13px"><strong>${en?'Reference':'Kaynak'}:</strong> ${link(selected.source,esc(selected.source.label||'Reference'))}</div>`:''}<p><a class="secondary-button" href="${window.RealDevBank.href(window.RealDevBank.related(selected,window.realdevSnapshot?.()?.tasks||[]))}">${en?'Practice related questions →':'İlgili soruları çöz →'}</a></p></article>`:''}<div class="public-note">${en?'Sign in to add notes, revisit concepts and save learning gaps.':'Not eklemek, kavramlara sonra dönmek ve eksiklerini kaydetmek için giriş yap.'} <a href="/auth.html#/sign-up">${en?'Create an account':'Hesap oluştur'} →</a></div></section>`;}
function today(){const progress=Math.min(100,Math.round(state.completed/4*100));return `<div class="welcome-row"><div><h1>Merhaba, geliştirici</h1><p>Bugün küçük bir adım atalım. Önce düşün, sonra dene, en son açıkla.</p></div><div class="streak">✦ <strong>${state.completed}</strong> çalışma tamamlandı</div></div>
<section class="hero-card"><div class="hero-content"><div class="hero-overline"><span class="live-dot"></span> BUGÜNÜN ÇALIŞMASI · 15 DK</div><h2>Kodu yalnızca çalıştırma. Ne yaptığını da bil.</h2><p>React’te state güncellemesini tahmin et, ardından C# runtime’ının rolünü kendi cümlelerinle anlat.</p><div class="hero-meta"><span>◉ Kod okuma</span><span>↗ Kavram açıklama</span><span>◷ 4 kısa adım</span></div></div><button class="primary-button" data-action="start-quiz">Çalışmaya başla <span>→</span></button></section>
<div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Bugünkü rota</h2><button class="subtle-link" data-view="map">Tüm beceriler →</button></div><div class="task-list"><div class="task-row" data-action="start-quiz"><span class="task-icon purple">⌘</span><span class="task-copy"><strong>Kod davranışını tahmin et</strong><small>React · state ve yeniden render</small></span><span class="task-time">4 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="errors"><span class="task-icon orange">⌁</span><span class="task-copy"><strong>Bir Git hatasını çöz</strong><small>non-fast-forward · güvenli inceleme</small></span><span class="task-time">5 dk</span><span class="task-arrow">›</span></div><div class="task-row" data-view="concepts"><span class="task-icon blue">▤</span><span class="task-copy"><strong>Bir kavramı kendi cümlenle açıkla</strong><small>C# · Common Language Runtime</small></span><span class="task-time">3 dk</span><span class="task-arrow">›</span></div></div><div class="panel-foot"><span>İlerleme bu cihazda kaydedilir</span><span>${progress}% rota</span></div></section>
<section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Beceri haritandan</h2><span class="eyebrow">KEŞİF AŞAMASI</span></div><div class="skill-list"><div class="skill-row"><span class="skill-name">React · kod okuma</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">C# · .NET temelleri</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div><div class="skill-row"><span class="skill-name">Git · hata çözme</span><span class="skill-state">${state.errorSolved?'bir görev tamamlandı':'ölçülmedi'}</span><div class="skill-track"><div class="skill-fill" style="width:${state.errorSolved?25:0}%"></div></div></div><div class="skill-row"><span class="skill-name">Unity · C#</span><span class="skill-state">ölçülmedi</span><div class="skill-track"><div class="skill-fill warm" style="width:0"></div></div></div></div><div class="panel-foot"><span>İlk kısa tarama ile başlangıç seviyesi oluşur.</span></div></section></div>
<div class="tip-card"><span class="tip-spark">✳</span><div><strong>Çalışma ipucu</strong><p>AI’ın ürettiği bir kodu kullanmadan önce kendine sor: Girdi ne? Çıktı ne? Hata olursa ilk hangi kanıta bakarım?</p></div></div>
<div class="section-label">Güncel gelişmeler</div><div class="news-inline">${news.slice(0,2).map((n,i)=>`<article class="news-mini"><div class="source-line"><span>${n.date} · ${n.tag}</span><span class="source-badge">${n.kind}</span></div><h3>${n.title}</h3><p>${n.body}</p><button class="text-button" data-view="news">Haberleri gör →</button></article>`).join('')}</div>`}
function quizView(){if(!state.quizMode)return `${heading('BECERİ TARAMASI','Neleri gerçekten anladığını keşfet','Kısa görevler kod okuma, hata teşhisi ve teknik anlatım pratiği sunar. “Bilmiyorum” demek de geçerli bir başlangıçtır.',`<span class="day-pill">10–15 dakika</span>`)}<section class="quiz-card"><p class="quiz-context">Önce kendin dene, sonra açıklamayı ve kaynağı incele.</p><button class="primary-button" data-action="start-quiz">Tarama görevlerine başla <span>→</span></button></section>`;return quizCard()}function quizCard(){const q=quiz[state.quizIndex];if(!q)return `<section class="quiz-card"><div class="eyebrow">TARAMA TAMAMLANDI</div><h2 class="quiz-question" style="margin-top:10px">İlk keşif turu bitti.</h2><p class="quiz-context">${state.completed} kısa görev tamamladın. Bu ilk tur yalnızca başlangıç sinyali; daha doğru beceri haritası için düzenli pratikte farklı örnekler de çözeceğiz.</p><button class="primary-button" data-action="reset-quiz">Bir tur daha yap <span>→</span></button> <button class="secondary-button" data-view="today">Bugüne dön</button></section>`;return `<section class="quiz-card"><div class="quiz-top"><span class="eyebrow">BAŞLANGIÇ TARAMASI · ${q.area}</span><span class="quiz-step">${state.quizIndex+1} / ${quiz.length}</span></div><div class="progress"><span style="width:${(state.quizIndex+1)/quiz.length*100}%"></span></div><h2 class="quiz-question">${q.question}</h2><p class="quiz-context">${q.context}</p>${q.code?`<div class="code-block">${esc(q.code)}</div>`:''}<div class="choice-list" style="margin-top:${q.code?'15px':'0'}">${choiceOrder('quiz:'+state.quizIndex,q.options.length).map((i,position)=>`<button class="choice ${state.selected===i?'selected':''}" data-choice="${i}" ${state.answered?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+position)}</span><span>${esc(q.options[i].text)}</span></button>`).join('')}</div>${state.answered?feedbackBox(state.selected===q.answer,q.options[state.selected],q.options[q.answer],{ok:'Doğru.',wrong:'Bu seçenek doğru değil.',skip:'Sorun değil, doğru cevap şöyle.',picked:'Seçtiğin neden yanlış:',right:'Doğru cevap:'},link(q.source,'Bilgiyi doğrula')):''}<div class="quiz-actions"><span class="text-muted">${state.answered?'Cevabın ve açıklama kaydedildi.':'Emin değilsen “Şimdilik bilmiyorum” diyebilirsin.'}</span>${state.answered?`<button class="primary-button" data-action="next-quiz">${state.quizIndex===quiz.length-1?'Tamamla':'Sonraki'} <span>→</span></button>`:`<button class="secondary-button" data-action="dont-know">Şimdilik bilmiyorum</button>`}</div></section>`}
function mapView(){return `${heading('GELİŞİMİN','Beceri haritam','Bu ilk prototipte görev cevapları cihazında saklanır. Alanlar görevlerle zaman içinde keşfedilir; henüz değerlendirilmemiş beceriye seviye atamayız.')}<div class="two-col"><section class="panel panel-pad"><div class="panel-title-row"><h2 class="panel-title">Çalışma alanları</h2><span class="eyebrow">HEDEF: GENEL EKSİKLERİ KAPAT</span></div><div class="skill-list">${[['Frontend','JavaScript · TypeScript · React'],['Backend','Java · Python · C# / .NET'],['Veritabanı','SQL · veri modeli · DDL'],['Git ve ekip çalışması','branch · merge · pull request'],['Test ve kalite','unit · integration · debug'],['DevOps ve cloud','CI/CD · AWS temelleri'],['Unity ve mobil oyun','C# · oyun döngüsü · build'],['AI ile üretim','kod açıklama · doğrulama']].map(x=>`<div class="task-row"><span class="task-icon purple">◇</span><span class="task-copy"><strong>${x[0]}</strong><small>${x[1]}</small></span><span class="chip">Henüz ölçülmedi</span></div>`).join('')}</div></section><aside class="panel panel-pad"><h2 class="panel-title">Ölçüm nasıl işler?</h2><p class="quiz-context" style="margin-top:12px">Bir doğru cevap tek başına “uzman” anlamına gelmez. Kod yazma, açıklama, hata ayıklama ve yeni senaryoya aktarım farklı görevlerle gözlemlenir.</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Önce bağımsız dene</strong><p>İpucu almadan ne yapabildiğin görünür.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Gerekince ipucu al</strong><p>Hangi yardımın gerektiği de ilerlemeni açıklar.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>Başka örnekte tekrar et</strong><p>Bilgiyi yeni duruma uygulamanı kontrol ederiz.</p></div></div></div><button class="primary-button" style="margin-top:16px" data-action="start-quiz">Kısa taramayı başlat <span>→</span></button></aside></div>`}
function errorsView(){return `${heading('HATA LABORATUVARI','Hata mesajını okuyup çözüm yolunu bul','Gerçekçi çıktıları incele: mesaj ne söylüyor, neyi henüz bilmiyorsun ve hangi kanıtı toplarsın?')}<div class="two-col"><section class="feature-card"><div class="eyebrow">GIT · PUSH HATASI · BAŞLANGIÇ</div><h2 class="quiz-question" style="margin-top:10px">Uzak branch ileride görünüyor</h2><div class="error-meta"><span class="chip red">non-fast-forward</span><span class="chip">Git</span><span class="chip">Güvenli teşhis</span></div><div class="code-block">! [rejected] main -&gt; main (non-fast-forward)\nerror: failed to push some refs\nhint: Updates were rejected because the tip of your current branch is behind its remote counterpart.</div><p class="quiz-context" style="margin-top:15px">Şu an <code>main</code> branch’indesin. Ekip arkadaşın uzak branch’e commit gönderdi; sende henüz fetch edilmemiş. İlk ne yaparsın?</p><textarea id="errorAnswer" class="answer-area" placeholder="Önce şunu kontrol ederim… çünkü…">${esc(state.answerText)}</textarea><div class="answer-tools"><button class="mic-button" data-action="mic">🎙 Sesli açıkla</button><button class="primary-button" data-action="check-error">Yanıtımı kaydet <span>→</span></button><button class="subtle-link" data-action="hint">İpucu ${state.errorHint?'gösterildi':''}</button></div>${state.errorHint?`<div class="result-box" style="margin-top:13px"><h4>İpucu</h4>Önce yerel çalışma ağacını ve branch’in uzakla ilişkisini incele. <code>git fetch</code> uzak bilgileri indirir ama dosyalarını birleştirmez. Ardından commit farkını görüp ekip akışına uygun merge veya rebase planla.</div>`:''}${state.errorSolved?`<div class="result-box"><h4>Yanıtın bu cihazda saklandı; otomatik doğruluk puanı yok.</h4>${/--force|push\s+-f/i.test(state.answerText)?'Force push paylaşılan geçmişi değiştirebilir; ekip akışını ve remote geçmişini incelemeden kullanma.':'Güvenli bir teşhis yolu; önce git status/git fetch ile uzak farkı incele, sonra ekip akışına uygun merge veya rebase seç, test et ve pushla.'} ${link(sources.git,'Git merge dokümanı')}</div>`:''}</section><aside class="panel panel-pad"><h2 class="panel-title">Hata ayıklama sırası</h2><p class="quiz-context" style="margin:8px 0 17px">Mesajı gördüğünde kendine şu soruları sor:</p><div class="error-steps"><div class="error-step"><span class="number">1</span><div><strong>Ne başarısız oldu?</strong><p>Komut ve hata türünü mesajdan ayır.</p></div></div><div class="error-step"><span class="number">2</span><div><strong>Hangi bilgi eksik?</strong><p>Branch durumu, son commit ve remote farkı.</p></div></div><div class="error-step"><span class="number">3</span><div><strong>En risksiz kanıtı topla</strong><p>git status, git branch -vv, git fetch.</p></div></div><div class="error-step"><span class="number">4</span><div><strong>Sonucu doğrula</strong><p>Çözümden sonra test edip push durumuna bak.</p></div></div></div><div class="source-note" style="margin-top:17px"><strong>Kaynak standardı:</strong> Öğretici adımlar resmi araç dokümantasyonuyla karşılaştırılır. Topluluk cevapları örnek olabilir; tek başına doğruluk kanıtı sayılmaz.</div></aside></div><div class="section-label">Sonraki hata konuları</div><div class="github-grid">${[['IDE ve SDK','dotnet SDK bulunamadı','PATH ve yüklenen SDK sürümlerini incele.'],['API ve tarayıcı','CORS hatası','Tarayıcı policy’sini ve response başlıklarını ayır.'],['Unity build','Android build başarısız','İlk gerçek error satırını ve build ortamını bul.']].map((x,i)=>`<article class="practice-tile" data-action="coming-error"><span>YAKINDA · ${['.NET','HTTP','UNITY'][i]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>`}
function conceptsView(){const cards=[...concepts,...expandedConcepts],c=cards.find(x=>x.id===state.conceptOpen);return `${heading('KAVRAM ATÖLYESİ','Adını duydun. Şimdi gerçekten anla.',`${cards.length} kaynaklı kavram · Git’te günlük branch akışından conflict ve geçmişi geri almaya kadar. Önce kısa anlatım, sonra kendi cümlenle açıkla.`)}<label class="concept-search-label" for="conceptSearch">Kavram veya Git komutu ara</label><input id="conceptSearch" class="concept-search" type="search" placeholder="Örn. API, cache, git rebase…" autocomplete="off"><p id="conceptSearchCount" class="concept-search-count" aria-live="polite">${cards.length} kavram</p><div class="concept-grid">${cards.map(x=>`<article class="concept-card" data-concept="${x.id}"><span class="concept-type">${x.type}</span><h3>${x.name}</h3><p>${x.desc}</p><div class="concept-footer"><span>Kaynaklı anlatım</span><span>Öğren →</span></div></article>`).join('')}</div>${c?`<article class="concept-detail"><div class="eyebrow">${c.type}</div><h2>${c.name}</h2><p>${c.body}</p><div class="analogy"><strong>Bir örnekle düşün:</strong> ${c.analogy}</div><div class="source-note" style="margin-top:13px"><strong>Kontrol edilebilir kaynak:</strong> ${link(c.source,c.source.label)}</div><label for="conceptAnswer" class="field-label">Şimdi kendi cümlenle açıkla</label><textarea id="conceptAnswer" class="answer-area" placeholder="Bunu başka bir geliştiriciye şöyle anlatırdım…"></textarea><div class="answer-tools"><button class="mic-button" data-action="mic" data-target="conceptAnswer">🎙 Sesli anlat</button><button class="primary-button" data-action="check-concept">Açıklamamı gözden geçir <span>→</span></button><span class="text-muted">Bu prototipte otomatik yapay zekâ değerlendirmesi yok.</span></div><div id="conceptFeedback"></div></article>`:''}<div class="source-note" style="margin-top:15px"><strong>Bilgi disiplini:</strong> Tanımlar MDN, Git, GitHub, Kubernetes, PostgreSQL ve üretici belgeleri gibi kaynaklara bağlanır. Topluluk yazıları resmi davranış tanımının yerine geçmez.</div>`}
function newsView(){return `${heading('YAZILIM HABERLERİ','Gündemi takip et, etkisini anla','AI modelleri, geliştirici araçları ve altyapı gelişmeleri. Kaynağa git veya kısa özeti aç.',`<span class="day-pill">Kontrol: 5 Ekim 2026</span>`)}<div class="source-note"><strong>Güvenilirlik kuralı:</strong> Bu akıştaki kartlar ilk sürüm için elle seçilmiş kaynaklı örneklerdir, canlı haber akışı değildir. Yayın tarihi kaynak sayfasından alınmıştır. Her kartta asıl kaynağa gidebilirsin.</div><div class="news-list">${news.map((n,i)=>`<article class="news-card"><div class="news-card-top"><span class="source-badge">${n.kind}</span><span>${n.date}</span><span>·</span><span>${n.tag}</span></div><h3>${n.title}</h3><p>${n.body}</p><div class="news-summary ${state.newsSummaries[i]?'open':''}" id="summary-${i}"><strong>Kısa özet:</strong> ${n.summary}</div><div class="news-actions"><button data-action="summary" data-index="${i}">${state.newsSummaries[i]?'Özeti kapat':'Haberi özetle'}</button>${link(n.source,`Asıl kaynak: ${n.source.label}`)}</div></article>`).join('')}</div><div class="section-label">Kaynak yaklaşımı</div><div class="two-col"><section class="panel panel-pad"><h2 class="panel-title">Resmi kaynaklar</h2><p class="quiz-context" style="margin:8px 0 0">Sürüm, API davranışı ve yeni model özellikleri için önce ürün dokümantasyonu, changelog veya resmi proje blogu. Üçüncü taraf açıklamalar, kaynağa göreli yorumlarıyla sunulur.</p></section><section class="panel panel-pad"><h2 class="panel-title">Topluluk kaynakları</h2><p class="quiz-context" style="margin:8px 0 0">Medium ve Stack Overflow fikir, deneyim ve hata örnekleri bulmaya yardım eder. İçerikler yayımlanmadan önce birincil kaynaklarla doğrulanmalı; kişisel görüş, resmi bilgi gibi işaretlenmemeli.</p></section></div>`}
function githubView(){return `${heading('GITHUB PRATİĞİ','Ekipte kodu nasıl güvenle teslim edersin?','Commit ve branch’ten GitHub Actions’a: kavramı oku, senaryoda uygula, sonra kendi repo akışına taşı.')}<div class="source-note"><strong>Kaynak:</strong> Git’in resmi dokümantasyonu ve GitHub Docs/Changelog. Workflow davranışları değişebileceği için güncel sözdizimi kaynak sayfasından kontrol edilir.</div><div class="github-grid">${[['01 · GIT','Branch ve commit','Değişiklikleri küçük, anlamlı parçalara ayır.'],['02 · COLLABORATION','Pull request','Değişikliği incelet, tartış ve test sonuçlarını kontrol et.'],['03 · HATA','Merge conflict','İki değişiklik aynı satırları etkileyince kanıtla çöz.'],['04 · AUTOMATION','GitHub Actions','Workflow YAML ile build ve test adımlarını otomatikleştir.'],['05 · SECURITY','GITHUB_TOKEN','Workflow’a gereken en az izinleri ver.'],['06 · DEBUG','Kırmızı workflow','Başarısız job, step, log ve artefact’ı sırasıyla incele.']].map(x=>`<article class="practice-tile" data-action="${x[0].includes('HATA')?'goto-errors':'github-lesson'}"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="section-label">Örnek: Actions güncellemesi</div><article class="news-card"><div class="news-card-top"><span class="source-badge">Resmi changelog</span><span>3 Eylül 2026</span></div><h3>Runner sürüm sonunu izleme ve vulnerability-alerts token izni</h3><p>Bu changelog kaydı, runner sürüm deprecations bilgisi için API ve GITHUB_TOKEN'a yeni salt okunur izin eklenmesini anlatıyor.</p><div class="news-actions">${link(sources.github,'GitHub Changelog kaynağı')}</div></article>`}
function sourceConceptsView(){
 const bank=window.realdevContentBank||{cards:[],sources:{}},en=window.realdevLocale==='en';
 const say=v=>typeof v==='string'?v:(v?.[en?'en':'tr']||v?.tr||'');
 const cards=[...concepts,...expandedConcepts,...bank.cards.map(x=>({...x,sourceMeta:bank.sources[x.source],source:{label:bank.sources[x.source]?.name||x.source,url:bank.sources[x.source]?.url||'#'}}))];
 const c=cards.find(x=>x.id===state.conceptOpen), title=en?'CONCEPT WORKSHOP':'KAVRAM ATÖLYESİ';
 let html=heading(title,en?'Understand the term, then explain it.':'Kavramı anla, sonra kendin açıkla.',en?cards.length+' searchable cards across code, teamwork, data, operations, AI, mobile and games.':'Kod, ekip, veri, operasyon, yapay zekâ, mobil ve oyun geliştirmede '+cards.length+' aranabilir kavram kartı.');
 html+='<label class="concept-search-label" for="conceptSearch">'+(en?'Search concepts':'Kavramlarda ara')+'</label><input id="conceptSearch" class="concept-search" type="search" placeholder="'+(en?'e.g. API, React state, pooling…':'Örn. API, React state, pooling…')+'" autocomplete="off"><p id="conceptSearchCount" class="concept-search-count" aria-live="polite">'+cards.length+' '+(en?'concepts':'kavram')+'</p><div class="concept-grid">';
 html+=cards.map(x=>'<article class="concept-card" data-concept="'+esc(x.id)+'"><span class="concept-type">'+esc(say(x.type))+'</span><h3>'+esc(say(x.name))+'</h3><p>'+esc(say(x.desc))+'</p><div class="concept-footer"><span>'+(en?'Source linked':'Kaynak bağlı')+'</span><span>'+(en?'Learn →':'Öğren →')+'</span></div></article>').join('');
 html+='</div>';
 if(c){
  html+='<article class="concept-detail"><div class="eyebrow">'+esc(say(c.type))+'</div><h2>'+esc(say(c.name))+'</h2><div class="concept-body">'+esc(say(c.body)).replace(/\n/g,'<br>')+'</div><div class="analogy"><strong>'+(en?'Example:':'Bir örnekle düşün:')+'</strong> '+esc(say(c.analogy))+'</div><div class="source-note" style="margin-top:13px"><strong>'+(en?'Check the source:':'Kaynağı kontrol et:')+'</strong> '+link(c.source,c.source.label);
  if(c.sourceMeta)html+='<br><strong>'+(en?'License:':'Lisans:')+'</strong> '+esc(c.sourceMeta.license)+' <a href="'+esc(c.sourceMeta.licenseUrl)+'" target="_blank" rel="noopener noreferrer">'+(en?'License details':'Lisans ayrıntısı')+' ↗</a><br><strong>'+(en?'How we use it:':'Kullanım biçimi:')+'</strong> '+esc(c.sourceMeta.use);
  html+='</div><p><a class="secondary-button" href="'+window.RealDevBank.href(window.RealDevBank.related(c,window.realdevSnapshot?.()?.tasks||[]))+'">'+(en?'Practice related questions →':'İlgili soruları çöz →')+'</a></p><label for="conceptAnswer" class="field-label">'+(en?'Explain it in your own words':'Şimdi kendi cümlenle açıkla')+'</label><textarea id="conceptAnswer" class="answer-area" placeholder="'+(en?'I would explain this to another developer as…':'Bunu başka bir geliştiriciye şöyle anlatırdım…')+'"></textarea><div class="answer-tools"><button class="mic-button" data-action="mic" data-target="conceptAnswer">🎙 '+(en?'Explain aloud':'Sesli anlat')+'</button><button class="primary-button" data-action="check-concept">'+(en?'Review my explanation':'Açıklamamı gözden geçir')+' →</button><span class="text-muted">'+(en?'No automatic accuracy score is given.':'Açıklamaya otomatik doğruluk puanı verilmiyor.')+'</span></div><div id="conceptFeedback"></div></article>';
 }
 const sources=Object.values(bank.sources);
 html+='<details class="source-note" style="margin-top:15px"><summary><strong>'+(en?'Sources and reuse notes':'Kaynaklar ve yeniden kullanım notları')+'</strong> · '+sources.length+'</summary><div class="github-grid" style="margin-top:12px">';
 html+=sources.map(s=>'<article class="practice-tile"><h3>'+link(s,s.name)+'</h3><p>'+esc(s.license)+'</p><p>'+(en?'Use:':'Kullanım:')+' '+esc(s.use)+'</p>'+link({label:en?'License or terms':'Lisans / koşullar',url:s.licenseUrl},en?'License or terms':'Lisans / koşullar')+'</article>').join('');
 html+='</div><p>'+(en?'Cards are original RealDev explanations based on linked references. External question wording is not copied. Recheck individual asset notices and source versions before reuse.':'Kartlar, bağlantılı kaynaklara dayanan özgün RealDev anlatımlarıdır. Harici soru metinleri kopyalanmadı. İçerikleri yeniden kullanmadan önce dosya bazında lisans istisnalarını ve kaynak sürümlerini kontrol edin.')+'</p></details>';
 return html;
}
const renderers={today,quiz:quizView,map:mapView,errors:errorsView,concepts:sourceConceptsView,news:newsView,github:githubView,landing:publicLanding,demoQuiz:guestQuizView,demoConcepts:guestConceptsView};
const routePaths={calendar:'/calendar',today:'/today',quiz:'/quiz',map:'/map',route:'/route',history:'/history',topics:'/topics',notes:'/notes',library:'/library',lab:'/lab',interview:'/interview',errors:'/errors',concepts:'/concepts',news:'/news',github:'/github',codehistory:'/code-history',review:'/review',advanced:'/advanced',account:'/account',landing:'/',demoQuiz:'/demo/questions',demoConcepts:'/demo/concepts'};const routeNames=new Set(Object.keys(routePaths));const routeFromHash=()=>{const value=decodeURIComponent(location.hash.slice(1));return routeNames.has(value)?value:'today'};const normalizePath=()=>decodeURIComponent(location.pathname).replace(/\/+$/,'')||'/';const routeFromLocation=()=>{const path=normalizePath();if(path==='/'){if(location.hash){const legacy=routeFromHash();if(legacy!=='today')return legacy;}return 'today';}return Object.entries(routePaths).find(([view,target])=>target===path&&view!=='landing')?.[0]||'today'};const requestedView=document.body.dataset.realdevInitialView||routeFromLocation();let currentView=requestedView;if(location.hash)history.replaceState(null,'',routePaths[currentView]||'/');function updateDocumentSeo(view=currentView){const path=normalizePath();const pages={calendar:['Study calendar · RealDeveloper','Your private active study minutes and monthly learning calendar.'],today:['Today · RealDeveloper','Your private daily developer practice and progress summary.'],quiz:['Skill assessment · RealDeveloper','Assess your software development skills with practical questions and evidence-based feedback.'],map:['Skill map · RealDeveloper','Review your developer skill evidence, practice areas and next learning steps.'],route:['Learning route · RealDeveloper','Follow a personal developer learning route built from your practice evidence.'],history:['Answer history · RealDeveloper','Review your saved answers and revisit questions from your account.'],topics:['Question Bank · RealDeveloper','Choose an area, subtopic and level to practice questions.'],notes:['My notes · RealDeveloper','Review your private study notes and recorded learning gaps.'],library:['Question library · RealDeveloper','Revisit questions saved to your personal developer practice library.'],lab:['Code lab · RealDeveloper','Write and run supported practice code in an isolated learning environment.'],interview:['Interview and project practice · RealDeveloper','Practice technical interviews, staged projects, debugging and code review.'],errors:['Error lab · RealDeveloper','Practice diagnosing Git, API, IDE, .NET, Unity and deployment errors.'],concepts:['Software concepts · RealDeveloper','Study software engineering concepts with sourced explanations and examples.'],news:['Software development news · RealDeveloper','Follow software development updates with dates and links to their original sources.'],github:['GitHub practice · RealDeveloper','Practice Git, pull requests, collaboration and GitHub Actions workflows.'],codehistory:['Code history · RealDeveloper','Review code submissions and test results saved to your account.'],review:['Review a question · RealDeveloper','Return to questions saved for review and study their explanations.'],advanced:['Advanced practice · RealDeveloper','Continue advanced software engineering projects and technical practice.'],account:['Account and data · RealDeveloper','Manage your RealDeveloper profile, learning data and account settings.'],demoQuiz:['Sample developer questions · RealDeveloper','Try sample programming, debugging and software engineering questions in a temporary, unsaved preview.'],demoConcepts:['Software concept glossary · RealDeveloper','Browse ten sourced software engineering concept cards with references to original documentation.']};const data=pages[view]||pages.today;document.title=data[0];const set=(selector,value,attribute='content')=>{const el=document.querySelector(selector);if(el)el.setAttribute(attribute,value);};set('meta[name="description"]',data[1]);const indexable=path==='/'||path==='/demo/questions'||path==='/demo/concepts';set('meta[name="robots"]',indexable?'index, follow':'noindex, nofollow');set('meta[property="og:title"]',data[0]);set('meta[property="og:description"]',data[1]);set('meta[property="og:url"]',location.origin+path);set('link[rel="canonical"]',location.origin+path,'href');}function syncViewFromUrl(){const next=routeFromLocation();if(state.view===next){updateDocumentSeo(next);return;}currentView=next;state.quizMode=false;updateDocumentSeo(next);render();}Object.defineProperty(state,'view',{configurable:true,enumerable:true,get:()=>currentView,set:value=>{currentView=routeNames.has(value)?value:'today';const target=routePaths[currentView]||'/today';if(location.pathname!==target||location.hash)history.pushState(null,'',target);updateDocumentSeo(currentView);}});window.addEventListener('popstate',syncViewFromUrl);window.addEventListener('hashchange',syncViewFromUrl);updateDocumentSeo(currentView);function render(){const view=state.view;const guestView=view==='demoQuiz'?guestQuizView:view==='demoConcepts'?guestConceptsView:publicLanding;if(!signedIn){const decision=window.RealDevRoutes?.guestDecision?.({path:normalizePath(),signedIn,sessionKnown,canSignIn})||'render';if(decision==='wait'){document.body.classList.add('guest-mode');root.innerHTML=`<section class="session-pending" aria-busy="true" role="status"><p>${bilingual('Oturum kontrol ediliyor…','Checking your session…')}</p></section>`;return;}if(decision==='sign-in'){location.replace(window.RealDevRoutes.signInUrl(location.pathname+location.search));return;}document.body.classList.add('guest-mode');root.innerHTML=guestView();document.getElementById('crumbCurrent').textContent=bilingual('Açık önizleme','Public preview');document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));return;}document.body.classList.remove('guest-mode');const privateView=view==='landing'||view==='demoQuiz'||view==='demoConcepts'?'today':view;root.innerHTML=(renderers[privateView]||today)();const names={calendar:window.realdevLocale==='en'?'Study calendar':'Çalışma takvimim',advanced:window.realdevLocale==='en'?'Advanced practice':'İleri eğitim',interview:window.realdevLocale==='en'?'Interviews and projects':'Mülakat ve projeler',today:'Bugün',quiz:'Beceri taraması',map:'Beceri haritam',errors:'Hata laboratuvarı',concepts:'Kavramlar',news:'Yazılım haberleri',github:'GitHub pratiği',route:'Çalışma rotam',history:'Cevap geçmişim',topics:'Soru Bankası',notes:'Notlarım',account:'Hesabım',lab:'Kod alanı',codehistory:'Kod geçmişim',library:'Kütüphanem',review:'Soruyu tekrar incele'};document.getElementById('crumbCurrent').textContent=names[privateView]||'Bugün';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===privateView||(privateView==='quiz'&&b.dataset.view==='today')))}
window.realdevRender=render;
function go(view){if(!signedIn&&!['landing','demoQuiz','demoConcepts'].includes(view)){location.assign(window.RealDevRoutes?.signInUrl(routePaths[view]||location.pathname)||'/auth.html#/sign-in');return;}state.view=view;state.quizMode=false;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0)}
async function setSignedInUser(user){const wasSignedIn=signedIn;if(!user&&!sessionKnown){const config=await window.realdevAuthReady?.catch(()=>null);canSignIn=Boolean(config?.configured&&!config.error&&!config.localPreview);}sessionKnown=true;signedIn=Boolean(user?.emailVerified);window.realdevAuthenticated=signedIn;document.body.classList.toggle('guest-mode',!signedIn);if(signedIn){loadProgress();if(!wasSignedIn&&['landing','demoQuiz','demoConcepts'].includes(state.view))state.view='today';}else if(wasSignedIn){state.completed=0;state.errorSolved=false;state.answerText='';state.selected=null;state.answered=false;}render();}
window.realdevAuthStateChanged=setSignedInUser;
window.realdevSessionReady?.then(setSignedInUser);
document.addEventListener('click',event=>{if(signedIn)return;const publicView=event.target.closest('[data-public-view]');if(publicView){event.preventDefault();event.stopImmediatePropagation();const view=publicView.dataset.publicView;if(view==='demoQuiz'){choiceOrders.clear();guestQuizIndex=0;guestSelected=null;guestAnswered=false;}if(view==='landing')guestConceptOpen=null;state.view=view;render();window.scrollTo(0,0);return;}const choice=event.target.closest('[data-guest-choice]');if(choice&&state.view==='demoQuiz'&&!guestAnswered){event.preventDefault();event.stopImmediatePropagation();guestSelected=Number(choice.dataset.guestChoice);guestAnswered=true;render();return;}const next=event.target.closest('[data-guest-action="next"]');if(next){event.preventDefault();event.stopImmediatePropagation();guestQuizIndex++;guestSelected=null;guestAnswered=false;render();window.scrollTo(0,0);return;}const concept=event.target.closest('[data-guest-concept]');if(concept){event.preventDefault();event.stopImmediatePropagation();guestConceptOpen=concept.dataset.guestConcept;render();document.querySelector('.concept-detail')?.scrollIntoView({behavior:'smooth',block:'center'});return;}const gated=event.target.closest('[data-view],[data-action],[data-rd],[data-advanced],#profileOpen,#profileOpenTop,#reminderButton');if(gated){event.preventDefault();event.stopImmediatePropagation();location.assign(window.RealDevRoutes?.signInUrl(routePaths[gated.dataset.view]||location.pathname)||'/auth.html#/sign-in');}},true);
document.addEventListener('input',e=>{if(e.target.id!=='conceptSearch')return;const terms=e.target.value.toLocaleLowerCase('tr-TR').trim().split(/\s+/).filter(Boolean);let visible=0;document.querySelectorAll('.concept-card').forEach(card=>{const text=card.textContent.toLocaleLowerCase('tr-TR');const show=terms.every(term=>text.includes(term));card.hidden=!show;if(show)visible++});const count=document.getElementById('conceptSearchCount');if(count)count.textContent=`${visible} kavram`;});
document.addEventListener('click',e=>{const viewButton=e.target.closest('[data-view]');if(viewButton){go(viewButton.dataset.view);return}const choice=e.target.closest('[data-choice]');if(choice&&!state.answered){state.selected=Number(choice.dataset.choice);state.answered=true;if(state.selected===quiz[state.quizIndex].answer)state.completed++;save();render();return}const concept=e.target.closest('[data-concept]');if(concept){state.conceptOpen=concept.dataset.concept;render();document.querySelector('.concept-detail')?.scrollIntoView({behavior:'smooth',block:'center'});return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'start-quiz':choiceOrders.clear();state.view='quiz';state.quizMode=true;state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'next-quiz':state.quizIndex++;state.selected=null;state.answered=false;if(state.quizIndex>=quiz.length){state.view='quiz';state.quizMode=true}render();break;case'dont-know':state.selected=-1;state.answered=true;render();break;case'reset-quiz':state.quizIndex=0;state.selected=null;state.answered=false;render();break;case'hint':state.errorHint++;render();break;case'check-error':state.answerText=document.getElementById('errorAnswer').value.trim();if(!state.answerText){toast('Önce teşhis düşünceni yaz veya sesli anlat.');break}state.errorSolved=true;save();render();break;case'mic':startSpeech(a.dataset.target||'errorAnswer');break;case'check-concept':conceptFeedback();break;case'summary':{const i=Number(a.dataset.index);state.newsSummaries[i]=!state.newsSummaries[i];render();break}case'coming-error':toast('Bu senaryo ilk sürümde yakında eklenecek.');break;case'github-lesson':toast('Bu çalışma kartı sıradaki geliştirme adımında.');break;case'goto-errors':go('errors');break}});
function startSpeech(targetId){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Bu tarayıcı sesli yazmayı desteklemiyor. Yazılı yanıtı kullanabilirsin.');return}const r=new Speech();r.lang=window.realdevLocale==='en'?'en-US':'tr-TR';r.interimResults=false;r.onresult=ev=>{const el=document.getElementById(targetId);if(el){el.value+=(el.value?' ':'')+ev.results[0][0].transcript;state.answerText=el.value}};r.onerror=()=>toast('Ses tanınamadı. İstersen yazılı yanıt verebilirsin.');r.start();toast(window.realdevLocale==='en'?'Listening… explain in English.':'Dinliyorum… Türkçe açıklamanı yap.');}
function conceptFeedback(){const input=document.getElementById('conceptAnswer')?.value.trim();const box=document.getElementById('conceptFeedback');if(!input){box.innerHTML='<div class="result-box warning">Önce kendi cümlenle kısa bir açıklama yaz.</div>';return}const words=input.split(/\s+/).length;box.innerHTML=`<div class="result-box ${words<12?'warning':''}"><h4>${words<12?'Biraz daha açmayı dene.':'İyi bir başlangıç.'}</h4>${words<12?'Açıklamana ne işe yaradığını ve nerede kullanıldığını ekle.':'Açıklamanı kendin oluşturdun. Şimdi kaynak anlatımıyla karşılaştır: hangi noktayı eklerdin?'} Otomatik teknik doğruluk puanı vermiyoruz; bu prototip yanıtını sunucuya göndermiyor.</div>`;}
document.getElementById('menuButton').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
function profileKey(name){const uid=window.realdevCurrentUser?.uid;return signedIn&&uid?`realdev-profile:${uid}:${name}`:null}
function profile(){if(!signedIn){location.assign('/auth.html#/sign-in');return}const goal=document.getElementById('dailyGoal');goal.value=localStorage.getItem(profileKey('daily-goal'))||'15 dakika';const selected=JSON.parse(localStorage.getItem(profileKey('goals'))||'["Full stack","Oyun geliştirme"]');document.querySelectorAll('#goalOptions input').forEach(input=>input.checked=selected.includes(input.value));document.getElementById('profileDialog').showModal()};document.getElementById('profileOpen').addEventListener('click',profile);document.getElementById('profileOpenTop').addEventListener('click',profile);document.getElementById('saveProfile').addEventListener('click',()=>{if(!signedIn){location.assign('/auth.html#/sign-in');return}const goals=[...document.querySelectorAll('#goalOptions input:checked')].map(input=>input.value);if(!goals.length){toast('En az bir öğrenme hedefi seç.');return}localStorage.setItem(profileKey('daily-goal'),document.getElementById('dailyGoal').value);localStorage.setItem(profileKey('goals'),JSON.stringify(goals));document.getElementById('goalSubtitle').textContent=goals.join(' · ');document.getElementById('profileDialog').close();toast('Hedeflerin ve günlük süren hesabında saklandı.')});document.getElementById('reminderButton').addEventListener('click',()=>{if(!signedIn){location.assign('/auth.html#/sign-in');return}window.realdevReminders?.()});
render();


